const mongoose = require('mongoose');

// Stock (and optional price) for each shop item, per size. Product details
// - name, photos, description, base price, the list of sizes - live in
// Contentful; this is the business data that changes as things sell.
// Rows are keyed by the shop item's itemId (the stable ID orders
// reference, generated by the API) and size; items without sizes have one
// row with size null.
const inventorySchema = new mongoose.Schema(
  {
    itemId: { type: String, required: true, trim: true },
    size: { type: String, default: null, trim: true },
    stock: {
      type: Number,
      required: true,
      min: 0,
      validate: { validator: Number.isInteger, message: 'stock must be a whole number' },
    },
    // This size's price; null = the item's price from Contentful.
    price: { type: Number, default: null, min: 0 },
  },
  { timestamps: true, collection: 'inventory' }
);

inventorySchema.index({ itemId: 1, size: 1 }, { unique: true });

module.exports = mongoose.model('Inventory', inventorySchema);
